csrf.pseudocode:
def render_form(session):
    if 'csrf' not in session:
        session['csrf'] = random_token(32)  # 세션별 난수
    return form_with_hidden('csrf', session['csrf'])

def handle_post(session, request):
    token = request.form.get('csrf', '')
    # 공격자 사이트는 SOP 때문에 이 값을 읽을 수 없음
    if not constant_time_eq(token, session.get('csrf', '')):
        return 403  # 토큰 불일치 → 위조 요청 차단
    return process(request)
